#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n, k, f, b;
    string s;
    cin >> n >> k >> f >> b >> s;
    long long ones = count(s.begin(), s.end(), '1'), add = min(k, n - ones);
    if (!ones) {
        // All rest days: place the added days as one contiguous block.
        cout << add * f + max(0LL, add - 1) * b << "\n";
        return 0;
    }
    long long pairs = 0;
    for (int i = 1; i < n; i++) pairs += s[i - 1] == '1' && s[i] == '1';
    vector<int> gaps;  // lengths of interior runs of 0s
    for (int i = 0; i < n;) {
        if (s[i] == '1') {
            i++;
            continue;
        }
        int j = i;
        while (j < n && s[j] == '0') j++;
        if (i > 0 && j < n) gaps.push_back(j - i);
        i = j;
    }
    sort(gaps.begin(), gaps.end());
    long long remain = add, extra = 0;
    // Filling a whole interior gap joins two blocks: one extra bonus pair.
    for (int gap : gaps) {
        if (gap > remain) break;
        remain -= gap;
        extra++;
    }
    cout << (ones + add) * f + (pairs + add + extra) * b << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        long n = nextLong(), k = nextLong(), f = nextLong(), b = nextLong();
        String s = next();
        long ones = 0;
        for (int i = 0; i < n; i++) if (s.charAt(i) == '1') ones++;
        long add = Math.min(k, n - ones);
        if (ones == 0) {
            // All rest days: place the added days as one contiguous block.
            System.out.println(add * f + Math.max(0, add - 1) * b);
            return;
        }
        long pairs = 0;
        for (int i = 1; i < n; i++) if (s.charAt(i - 1) == '1' && s.charAt(i) == '1') pairs++;
        int[] gaps = new int[(int) n];  // lengths of interior runs of 0s
        int g = 0;
        for (int i = 0; i < n;) {
            if (s.charAt(i) == '1') {
                i++;
                continue;
            }
            int j = i;
            while (j < n && s.charAt(j) == '0') j++;
            if (i > 0 && j < n) gaps[g++] = j - i;
            i = j;
        }
        Arrays.sort(gaps, 0, g);
        long remain = add, extra = 0;
        // Filling a whole interior gap joins two blocks: one extra bonus pair.
        for (int i = 0; i < g; i++) {
            if (gaps[i] > remain) break;
            remain -= gaps[i];
            extra++;
        }
        System.out.println((ones + add) * f + (pairs + add + extra) * b);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k, f, b := nextInt(), nextInt(), nextInt(), nextInt()
	s := token()
	ones := 0
	for _, c := range s {
		if c == '1' {
			ones++
		}
	}
	add := min(k, n-ones)
	if ones == 0 {
		// All rest days: place the added days as one contiguous block.
		fmt.Println(add*f + max(0, add-1)*b)
		return
	}
	pairs := 0
	for i := 1; i < n; i++ {
		if s[i-1] == '1' && s[i] == '1' {
			pairs++
		}
	}
	gaps := []int{} // lengths of interior runs of 0s
	for i := 0; i < n; {
		if s[i] == '1' {
			i++
			continue
		}
		j := i
		for j < n && s[j] == '0' {
			j++
		}
		if i > 0 && j < n {
			gaps = append(gaps, j-i)
		}
		i = j
	}
	sort.Ints(gaps)
	remain, extra := add, 0
	// Filling a whole interior gap joins two blocks: one extra bonus pair.
	for _, gap := range gaps {
		if gap > remain {
			break
		}
		remain -= gap
		extra++
	}
	fmt.Println((ones+add)*f + (pairs+add+extra)*b)
}
